package net.officefloor.hq.app;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.officefloor.hq.app.people.Grade;
import net.officefloor.hq.app.people.Kind;
import net.officefloor.hq.app.people.State;
import net.officefloor.hq.app.people.Person;
import org.springframework.context.annotation.Profile;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.server.ResponseStatusException;

/**
 * Per-spec data setup for the end-to-end tests. Profile-guarded so it exists ONLY under the test
 * launch (bin/start sets spring.profiles.active=e2e) — never in a real deploy. Tests call these to
 * ARRANGE data; they ASSERT only through the UI.
 */
@Profile("e2e")
@RestController
@RequestMapping("/__test__")
public class TestSupportController {

    private static final Set<String> PERSON_FIELDS = Set.of("id", "name", "alpha", "beta", "gamma", "delta", "epsilon", "zeta", "grade", "kind", "onset", "active", "score", "state", "region");

    private static final Set<String> PATRON_FIELDS = Set.of("personId", "patronId");

    private static final Set<String> REGION_FIELDS = Set.of("personId", "region");

    private static final Set<String> FOLLOW_FIELDS = Set.of("from", "to");

    private static final Set<String> SHEET_FIELDS = Set.of("id", "anchor", "people", "patrons", "regions", "follows");

    private final Audit audit;
    private final JdbcTemplate jdbc;

    public TestSupportController(Audit audit, JdbcTemplate jdbc) {
        this.audit = audit;
        this.jdbc = jdbc;
    }

    /** Truncate all domain tables and clear the audit file so each spec starts clean. */
    @PostMapping("/reset")
    @Transactional
    public void reset() {
        audit.clear();
        // Person is referenced by its patrons, so delete rather than truncate.
        jdbc.update("DELETE FROM person_patron");
        jdbc.update("DELETE FROM person_follow");
        jdbc.update("DELETE FROM person_region");
        jdbc.update("DELETE FROM person");
        jdbc.update("DELETE FROM sheet");
        jdbc.update("DELETE FROM unnamed_sheet");
        jdbc.execute("ALTER TABLE person ALTER COLUMN id RESTART WITH 1");
    }

    /**
     * Insert the fixture a spec needs; the payload shape evolves with the schema. Store every field
     * given, or refuse with HTTP 400 naming it — never ignore one silently (AGENTS.md §4.2).
     */
    @PostMapping("/seed")
    @Transactional
    public void seed(@RequestBody Map<String, Object> fixture) {
        for (String key : fixture.keySet()) {
            if (!key.equals("anchor") && !key.equals("people") && !key.equals("patrons") && !key.equals("regions")
                    && !key.equals("follows") && !key.equals("sheets")) {
                throw badRequest("unknown fixture key: " + key);
            }
        }
        // The top-level anchor, people and patrons are the unnamed sheet's.
        LocalDate anchor = date(fixture.get("anchor"), "anchor");
        if (anchor != null) {
            jdbc.update("INSERT INTO unnamed_sheet (id, anchor) VALUES (1, ?)", anchor);
        }
        // People, patrons and regions at the top level are on the unnamed sheet.
        seedSheet(null, fixture.get("people"), fixture.get("patrons"), fixture.get("regions"), fixture.get("follows"), "");
        for (Map<String, Object> sheet : rows(fixture.get("sheets"), "sheets")) {
            for (String field : sheet.keySet()) {
                if (!SHEET_FIELDS.contains(field)) {
                    throw badRequest("cannot store sheets." + field);
                }
            }
            if (!(sheet.get("id") instanceof String id) || id.isBlank()) {
                throw badRequest("sheets.id is required");
            }
            jdbc.update("INSERT INTO sheet (id, anchor) VALUES (?, ?)", id, date(sheet.get("anchor"), "sheets.anchor"));
            seedSheet(id, sheet.get("people"), sheet.get("patrons"), sheet.get("regions"), sheet.get("follows"), "sheets.");
        }
    }

    private static String sheetWhere(String sheetId) {
        return sheetId == null ? "sheet_id IS NULL" : "sheet_id = ?";
    }

    private static Object[] sheetArgs(String sheetId, Object... more) {
        List<Object> args = new ArrayList<>();
        if (sheetId != null) {
            args.add(sheetId);
        }
        args.addAll(List.of(more));
        return args.toArray();
    }

    private long nextLocalId(String sheetId) {
        return jdbc.queryForObject("SELECT COALESCE(MAX(local_id), 0) + 1 FROM person WHERE " + sheetWhere(sheetId),
                Long.class, sheetArgs(sheetId));
    }

    /** The internal key of the person with an id on a sheet; refuses an id the sheet does not have. */
    private long internalId(String sheetId, long localId, String field) {
        List<Long> ids = jdbc.queryForList("SELECT id FROM person WHERE " + sheetWhere(sheetId) + " AND local_id = ?",
                Long.class, sheetArgs(sheetId, localId));
        if (ids.isEmpty()) {
            throw badRequest(field + " " + localId + " is not a person on the sheet");
        }
        return ids.get(0);
    }

    /** Inserts one sheet's people and then their patrons, regions and follows; a null sheet id is the unnamed sheet. */
    private void seedSheet(String sheetId, Object peopleRows, Object patronRows, Object regionRows, Object followRows,
            String prefix) {
        for (Map<String, Object> row : rows(peopleRows, prefix + "people")) {
            for (String field : row.keySet()) {
                if (!PERSON_FIELDS.contains(field)) {
                    throw badRequest("cannot store " + prefix + "people." + field);
                }
            }
            if (!(row.get("name") instanceof String name)) {
                throw badRequest(prefix + "people.name is required");
            }
            Integer alpha = integer(row.get("alpha"), prefix + "people.alpha");
            Integer beta = integer(row.get("beta"), prefix + "people.beta");
            Integer gamma = integer(row.get("gamma"), prefix + "people.gamma");
            Integer delta = integer(row.get("delta"), prefix + "people.delta");
            Integer epsilon = integer(row.get("epsilon"), prefix + "people.epsilon");
            Integer zeta = integer(row.get("zeta"), prefix + "people.zeta");
            String grade = grade(row.get("grade"), prefix + "people.grade");
            String kind = kind(row.get("kind"), prefix + "people.kind");
            LocalDate onset = date(row.get("onset"), prefix + "people.onset");
            Boolean active = bool(row.get("active"), prefix + "people.active");
            Integer score = integer(row.get("score"), prefix + "people.score");
            String state = state(row.get("state"), prefix + "people.state");
            // A person's id is their id within the sheet; the internal key is generated.
            Integer givenId = integer(row.get("id"), prefix + "people.id");
            long localId = givenId != null ? givenId : nextLocalId(sheetId);
            jdbc.update("INSERT INTO person (sheet_id, local_id, name, alpha, beta, gamma, delta, epsilon, zeta, grade, kind, onset, active, score, state) "
                    + "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
                    sheetId, localId, name, alpha, beta, gamma, delta, epsilon, zeta, grade, kind, onset,
                    active != null ? active : true, score, state != null ? state : State.DRAFT.name());
            // A person's single region (from before people had several) is one of their regions.
            String region = text(row.get("region"), prefix + "people.region");
            if (region != null) {
                jdbc.update("MERGE INTO person_region (person_id, region) KEY (person_id, region) VALUES (?, ?)",
                        internalId(sheetId, localId, prefix + "people.id"), region);
            }
        }
        // Patrons link people by id, so add them once every person exists.
        for (Map<String, Object> row : rows(patronRows, prefix + "patrons")) {
            for (String field : row.keySet()) {
                if (!PATRON_FIELDS.contains(field)) {
                    throw badRequest("cannot store " + prefix + "patrons." + field);
                }
            }
            Integer personId = integer(row.get("personId"), prefix + "patrons.personId");
            Integer patronId = integer(row.get("patronId"), prefix + "patrons.patronId");
            if (personId == null || patronId == null) {
                throw badRequest(prefix + "patrons rows need personId and patronId");
            }
            jdbc.update("INSERT INTO person_patron (person_id, patron_id) VALUES (?, ?)",
                    internalId(sheetId, personId, prefix + "patrons.personId"),
                    internalId(sheetId, patronId, prefix + "patrons.patronId"));
        }
        // Regions link a person by id to each region they belong to.
        for (Map<String, Object> row : rows(regionRows, prefix + "regions")) {
            for (String field : row.keySet()) {
                if (!REGION_FIELDS.contains(field)) {
                    throw badRequest("cannot store " + prefix + "regions." + field);
                }
            }
            Integer personId = integer(row.get("personId"), prefix + "regions.personId");
            String region = text(row.get("region"), prefix + "regions.region");
            if (personId == null || region == null) {
                throw badRequest(prefix + "regions rows need personId and region");
            }
            jdbc.update("MERGE INTO person_region (person_id, region) KEY (person_id, region) VALUES (?, ?)",
                    internalId(sheetId, personId, prefix + "regions.personId"), region);
        }
        // Follows link a follower to the person they follow, by id; one direction only.
        for (Map<String, Object> row : rows(followRows, prefix + "follows")) {
            for (String field : row.keySet()) {
                if (!FOLLOW_FIELDS.contains(field)) {
                    throw badRequest("cannot store " + prefix + "follows." + field);
                }
            }
            Integer from = integer(row.get("from"), prefix + "follows.from");
            Integer to = integer(row.get("to"), prefix + "follows.to");
            if (from == null || to == null) {
                throw badRequest(prefix + "follows rows need from and to");
            }
            if (from.equals(to)) {
                throw badRequest(prefix + "follows: a person cannot follow themselves");
            }
            jdbc.update("INSERT INTO person_follow (follower_id, followed_id) VALUES (?, ?)",
                    internalId(sheetId, from, prefix + "follows.from"), internalId(sheetId, to, prefix + "follows.to"));
        }
    }

    /**
     * Read back what is stored, in the same shape and with the same field names the fixtures use,
     * so earlier checkpoints' test data can be replayed and checked (AGENTS.md §4.3, §4.4). The
     * unnamed sheet's people are at the top level; each named sheet nests its own.
     */
    @GetMapping("/fixture")
    public Map<String, Object> fixture() {
        Map<String, Object> out = new LinkedHashMap<>();
        for (String anchor : jdbc.queryForList("SELECT CAST(anchor AS VARCHAR) FROM unnamed_sheet WHERE anchor IS NOT NULL",
                String.class)) {
            out.put("anchor", anchor);
        }
        out.putAll(sheetContents(null));
        List<Map<String, Object>> sheets = new ArrayList<>();
        for (Map<String, Object> row : jdbc.queryForList("SELECT id, CAST(anchor AS VARCHAR) AS anchor FROM sheet ORDER BY id")) {
            Map<String, Object> sheet = new LinkedHashMap<>();
            sheet.put("id", row.get("id"));
            if (row.get("anchor") != null) {
                sheet.put("anchor", row.get("anchor"));
            }
            String id = (String) row.get("id");
            sheet.putAll(sheetContents(id));
            sheets.add(sheet);
        }
        out.put("sheets", sheets);
        return out;
    }

    private Map<String, Object> sheetContents(String sheetId) {
        String where = sheetId == null ? "p.sheet_id IS NULL" : "p.sheet_id = ?";
        Object[] args = sheetId == null ? new Object[0] : new Object[] {sheetId};
        Map<String, Object> out = new LinkedHashMap<>();
        out.put("people", jdbc.queryForList("SELECT local_id AS \"id\", name AS \"name\", alpha AS \"alpha\", "
                + "beta AS \"beta\", gamma AS \"gamma\", delta AS \"delta\", epsilon AS \"epsilon\", zeta AS \"zeta\", grade AS \"grade\", kind AS \"kind\", "
                + "CAST(onset AS VARCHAR) AS \"onset\", active AS \"active\", score AS \"score\", state AS \"state\", "
                + "(SELECT MIN(pr.region) FROM person_region pr WHERE pr.person_id = p.id) AS \"region\" FROM person p WHERE " + where + " ORDER BY local_id", args));
        out.put("patrons", jdbc.queryForList("SELECT p.local_id AS \"personId\", o.local_id AS \"patronId\" "
                + "FROM person_patron pp JOIN person p ON p.id = pp.person_id JOIN person o ON o.id = pp.patron_id "
                + "WHERE " + where + " ORDER BY p.local_id, o.local_id", args));
        out.put("regions", jdbc.queryForList("SELECT p.local_id AS \"personId\", pr.region AS \"region\" "
                + "FROM person_region pr JOIN person p ON p.id = pr.person_id "
                + "WHERE " + where + " ORDER BY p.local_id, pr.region", args));
        out.put("follows", jdbc.queryForList("SELECT p.local_id AS \"from\", o.local_id AS \"to\" "
                + "FROM person_follow pf JOIN person p ON p.id = pf.follower_id JOIN person o ON o.id = pf.followed_id "
                + "WHERE " + where + " ORDER BY p.local_id, o.local_id", args));
        return out;
    }

    @SuppressWarnings("unchecked")
    private static List<Map<String, Object>> rows(Object value, String key) {
        if (value == null) {
            return List.of();
        }
        if (!(value instanceof List<?> list) || !list.stream().allMatch(r -> r instanceof Map)) {
            throw badRequest(key + " must be a list of rows");
        }
        return (List<Map<String, Object>>) list;
    }

    private static Integer integer(Object value, String field) {
        if (value == null) {
            return null;
        }
        if (value instanceof Number n && n.doubleValue() == Math.rint(n.doubleValue())) {
            return n.intValue();
        }
        if (value instanceof String s && s.matches("-?\\d+")) {
            return Integer.valueOf(s);
        }
        throw badRequest(field + " must be a whole number, got " + value);
    }

    private static String grade(Object value, String field) {
        if (value == null) {
            return null;
        }
        try {
            return Grade.parse(String.valueOf(value)).name();
        } catch (IllegalArgumentException e) {
            throw badRequest(field + ": " + e.getMessage());
        }
    }

    private static String kind(Object value, String field) {
        if (value == null) {
            return null;
        }
        try {
            return Kind.parse(String.valueOf(value)).name();
        } catch (IllegalArgumentException e) {
            throw badRequest(field + ": " + e.getMessage());
        }
    }

    private static String state(Object value, String field) {
        if (value == null) {
            return null;
        }
        try {
            return State.parse(String.valueOf(value)).name();
        } catch (IllegalArgumentException e) {
            throw badRequest(field + ": " + e.getMessage());
        }
    }

    private static String text(Object value, String field) {
        if (value == null) {
            return null;
        }
        if (!(value instanceof String s)) {
            throw badRequest(field + " must be text, got " + value);
        }
        if (s.length() > Person.REGION_MAX_LENGTH) {
            throw badRequest(field + " must be at most " + Person.REGION_MAX_LENGTH + " characters, got " + s);
        }
        return s;
    }

    private static Boolean bool(Object value, String field) {
        if (value == null) {
            return null;
        }
        if (value instanceof Boolean b) {
            return b;
        }
        if (value instanceof String s && (s.equals("true") || s.equals("false"))) {
            return Boolean.valueOf(s);
        }
        throw badRequest(field + " must be true or false, got " + value);
    }

    private static LocalDate date(Object value, String field) {
        if (value == null) {
            return null;
        }
        try {
            return LocalDate.parse(String.valueOf(value));
        } catch (DateTimeParseException e) {
            throw badRequest(field + " must be a date as yyyy-mm-dd, got " + value);
        }
    }

    private static ResponseStatusException badRequest(String message) {
        return new ResponseStatusException(HttpStatus.BAD_REQUEST, message);
    }
}
package net.officefloor.hq.app.people;

import jakarta.persistence.CollectionTable;
import jakarta.persistence.Column;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.JoinTable;
import jakarta.persistence.ManyToMany;
import jakarta.persistence.Table;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import java.util.Collection;
import java.util.Comparator;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

/** A person on the list: a name and whole-number "alpha", "beta" and "gamma" (each absent until
 * given), a second raw axis of whole-number "delta" and "epsilon" (each absent until given) with the derived "force"
 * (delta × epsilon), a whole-number "zeta" (absent until given) with the derived "sway"
 * (zeta − delta) and "torque" (force + 3 × sway), each absent while any of delta, epsilon or zeta is, "blend" (momentum + torque, absent while either is), "flux" (the average of the patrons' force, rounded down, zero without patrons), "crest" (blend + flux, absent while either is), "swing" (the positive torque of the people followed added together, zero without any), "haul" (crest + swing, absent while either is), "vector" (the average of the patrons' blend, rounded down, zero without patrons), and the derived "thrust" (alpha × beta), "drift" (gamma − alpha) and "momentum"
 * (thrust + 3 × drift), which are absent until all three raw values are given. A person may have
 * any number of "patrons": other people on the list, whose thrust added together is the person's
 * "backing". A person belongs to one sheet (null for the unnamed sheet) and is numbered within it, so sheets never share people. "Net" is momentum plus backing (backing counted as zero without patrons). A person may have a
 * "grade" (LOW, MID or HIGH; absent until given), from which their "weight" is 1, 3 or 5. "Load" is momentum times weight.
 * A person may have a "kind" (A, B or C; absent until given), from which their "verge" is 2, 3 or 5.
 * "Pivot" is torque times verge, absent while either is. "Yield" is pivot plus two times lift, absent while either is. "Grip" is yield minus coil, absent while either is. "Charge" is vector plus yield, absent while either is. "Churn" is tide minus vector, absent while either is. "Flow" is yield plus charge, absent while either is.
 * A person may have an "onset" date (absent until given); their "age" is the complete weeks from onset to the sheet's anchor.
 * "Decay" is momentum minus age. A person is "active" or not; a new person is active. "Clout" is the average of the
 * patrons' effective, rounded down (zero without patrons). "Influence" is effective plus clout. "Brace" is influence plus two times force. "Tide" is the brace of the people followed added together, each followed brace taken as their momentum plus two times force and only positive braces counted (zero without any). "Strain" is crest minus brace. "Pulse" classifies strain against a tolerance band of 10 either side of zero.
 * A person may belong to any number of "regions": short codes typed in, like N1 or S2. A region's
 * "multiplier" comes from its first letter: N is 2, S is 3, any other is 1. "Reach" is the sum, over the
 * person's regions, of momentum times that region's multiplier. "Gust" is reach plus two times torque. "Coil" is gust minus momentum. A person may follow any number of other people on
 * the list, without being followed back; their "allies" are the people they follow. "Synergy" is the
 * allies' thrust added together (zero without allies). "Combined" is influence plus synergy.
 * A person may have a whole-number "score" (absent until given); their "note sum" is the score (zero
 * without one) and their "quality" is the score (absent without one). A person has a workflow "state",
 * starting at DRAFT and moved forward to REVIEW and then FINAL; a FINAL person may be reopened to REWORK
 * and moved forward to FINAL again. */
@Entity
@Table(name = "person")
public class Person {

    /** The longest region code that can be stored. */
    public static final int REGION_MAX_LENGTH = 16;

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    /** The person's id within their sheet; the id the user and the API see. */
    @Column(name = "local_id")
    private Long localId;

    private String name;

    private Integer alpha;

    private Integer beta;

    private Integer gamma;

    private Integer delta;

    private Integer epsilon;

    private Integer zeta;

    @Enumerated(EnumType.STRING)
    private Grade grade;

    @Enumerated(EnumType.STRING)
    private Kind kind;

    private LocalDate onset;

    private boolean active = true;

    @Enumerated(EnumType.STRING)
    private State state = State.DRAFT;

    /** The id of the sheet the person belongs to; null for the unnamed sheet. */
    @Column(name = "sheet_id")
    private String sheetId;

    @ManyToMany(fetch = FetchType.EAGER)
    @JoinTable(name = "person_patron", joinColumns = @JoinColumn(name = "person_id"),
            inverseJoinColumns = @JoinColumn(name = "patron_id"))
    private Set<Person> patrons = new HashSet<>();

    /** The people this person follows: their allies. Following is one-directional. */
    @ManyToMany(fetch = FetchType.EAGER)
    @JoinTable(name = "person_follow", joinColumns = @JoinColumn(name = "follower_id"),
            inverseJoinColumns = @JoinColumn(name = "followed_id"))
    private Set<Person> follows = new HashSet<>();

    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_region", joinColumns = @JoinColumn(name = "person_id"))
    @Column(name = "region")
    private Set<String> regions = new HashSet<>();

    private Integer score;

    protected Person() {
    }

    public Person(String sheetId, long localId, String name, Integer alpha, Integer beta, Integer gamma) {
        this.sheetId = sheetId;
        this.localId = localId;
        this.name = name;
        this.alpha = alpha;
        this.beta = beta;
        this.gamma = gamma;
    }

    public Long getId() {
        return id;
    }

    public Long getLocalId() {
        return localId;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getName() {
        return name;
    }

    public Integer getAlpha() {
        return alpha;
    }

    public void setAlpha(Integer alpha) {
        this.alpha = alpha;
    }

    public Integer getBeta() {
        return beta;
    }

    public void setBeta(Integer beta) {
        this.beta = beta;
    }

    public Integer getGamma() {
        return gamma;
    }

    public void setGamma(Integer gamma) {
        this.gamma = gamma;
    }

    public Integer getDelta() {
        return delta;
    }

    public void setDelta(Integer delta) {
        this.delta = delta;
    }

    public Integer getEpsilon() {
        return epsilon;
    }

    public void setEpsilon(Integer epsilon) {
        this.epsilon = epsilon;
    }

    public Integer getZeta() {
        return zeta;
    }

    public void setZeta(Integer zeta) {
        this.zeta = zeta;
    }

    public Grade getGrade() {
        return grade;
    }

    public void setGrade(Grade grade) {
        this.grade = grade;
    }

    public Kind getKind() {
        return kind;
    }

    public void setKind(Kind kind) {
        this.kind = kind;
    }

    public boolean isActive() {
        return active;
    }

    public void setActive(boolean active) {
        this.active = active;
    }

    public State getState() {
        return state;
    }

    public void setState(State state) {
        this.state = state;
    }

    /** The regions, sorted ascending. */
    public List<String> getRegions() {
        return regions.stream().sorted().toList();
    }

    public void setRegions(Collection<String> regions) {
        this.regions = new HashSet<>(regions);
    }

    public Integer getScore() {
        return score;
    }

    public void setScore(Integer score) {
        this.score = score;
    }

    /** The note sum is the score; zero without one. */
    public int getNoteSum() {
        return score == null ? 0 : score;
    }

    /** Quality is the score; absent without one. */
    public Integer getQuality() {
        return score;
    }

    /** Adjusted is combined plus quality (quality counted as zero without a score); absent while combined is. */
    public Integer getAdjusted() {
        Integer combined = getCombined();
        Integer quality = getQuality();
        return combined == null ? null : combined + (quality == null ? 0 : quality);
    }

    public LocalDate getOnset() {
        return onset;
    }

    /** Age is the complete seven-day weeks from onset to the anchor (leftover days dropped), negative when onset is
     * after it and truncated toward zero; absent without an onset. */
    public Long getAge(LocalDate anchor) {
        return onset == null ? null : ChronoUnit.WEEKS.between(onset, anchor);
    }

    /** Decay is momentum minus age; absent while either is absent. */
    public Long getDecay(LocalDate anchor) {
        Integer momentum = getMomentum();
        Long age = getAge(anchor);
        return momentum == null || age == null ? null : momentum - age;
    }

    /** Weight comes from the grade: LOW 1, MID 3, HIGH 5; absent without a grade. */
    public Integer getWeight() {
        return grade == null ? null : grade.weight();
    }

    /** Verge comes from the kind: A 2, B 3, C 5; absent without a kind. */
    public Integer getVerge() {
        return kind == null ? null : kind.verge();
    }

    /** The patrons, sorted by name. */
    public List<Person> getPatrons() {
        return patrons.stream()
                .sorted(Comparator.comparing(Person::getName).thenComparing(Person::getId))
                .toList();
