281	    /** A person's view, ranked among the people on their sheet. */
282	    private PersonView view(String sheetId, Person person) {
283	        List<Person> people = service.list(sheetId);
284	        return PersonView.of(person, ranks(people), medianScaled(people), meanBlend(people), service.anchor(sheetId));
285	    }
