287	    /**
288	     * Each person's rank by local id: 1 for the highest momentum, then 2, 3, ... with equal momentum
289	     * ordered by higher alpha, then by name. People without a momentum are not ranked.
290	     */
291	    private static Map<Long, Integer> ranks(List<Person> people) {
292	        List<Person> ranked = people.stream().filter(p -> p.getMomentum() != null).sorted(RANK_ORDER).toList();
293	        Map<Long, Integer> ranks = new HashMap<>();
294	        for (int i = 0; i < ranked.size(); i++) {
295	            ranks.put(ranked.get(i).getLocalId(), i + 1);
296	        }
297	        return ranks;
298	    }
