300	    /** The sheet named by the request, trimmed; blank or absent means the unnamed sheet. */
301	    private static String sheetId(String sheet) {
302	        return sheet == null || sheet.isBlank() ? null : sheet.trim();
303	    }
304	
305	    /** Regions as typed, each trimmed, leaving out blanks and repeats; none when absent. */
306	    static Set<String> regions(List<String> values) {
307	        Set<String> regions = new LinkedHashSet<>();
308	        if (values != null) {
309	            for (String value : values) {
310	                String region = region(value);
311	                if (region != null) {
312	                    regions.add(region);
313	                }
314	            }
315	        }
316	        return regions;
317	    }
318	
319	    /** A region as typed, trimmed; blank means none. Refuses one longer than {@link Person#REGION_MAX_LENGTH}. */
320	    static String region(String value) {
321	        if (value == null || value.isBlank()) {
322	            return null;
323	        }
324	        String region = value.trim();
325	        if (region.length() > Person.REGION_MAX_LENGTH) {
326	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
327	                    "region must be at most " + Person.REGION_MAX_LENGTH + " characters");
328	        }
329	        return region;
330	    }
331	
332	    private static Grade grade(Object value) {
333	        if (value == null) {
334	            return null;
335	        }
336	        try {
337	            return Grade.parse(String.valueOf(value));
338	        } catch (IllegalArgumentException e) {
339	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, e.getMessage());
340	        }
341	    }
342	
343	    private static Kind kind(Object value) {
344	        if (value == null) {
345	            return null;
346	        }
347	        try {
348	            return Kind.parse(String.valueOf(value));
349	        } catch (IllegalArgumentException e) {
350	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, e.getMessage());
351	        }
352	    }
353	
354	    private static Integer integer(Object value) {
355	        if (value == null) {
356	            return null;
357	        }
358	        if (value instanceof Integer i) {
359	            return i;
360	        }
361	        throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "expected a whole number, got " + value);
362	    }
