536	    /** Moves the person forward to their next state (REWORK back to FINAL), recorded in the audit as STATE_CHANGED id=.. from=.. to=...; refused once FINAL. */
537	    @Transactional
538	    public Optional<Person> advance(String sheetId, long id) {
539	        return people.findBySheetIdAndLocalId(sheetId, id).map(p -> {
540	            State previous = p.getState();
541	            State next = previous.next();
542	            if (next == null) {
543	                throw new IllegalStateException("a person at " + previous + " cannot move forward");
544	            }
545	            p.setState(next);
546	            audit.record("STATE_CHANGED id=" + id + " from=" + previous + " to=" + next);
547	            return p;
548	        });
549	    }
