554	        return people.findBySheetIdAndLocalId(sheetId, id).map(p -> {
555	            State current = p.getState();
556	            State reopened = current.reopened();
557	            if (reopened == null) {
558	                throw new IllegalStateException("a person at " + current + " cannot be reworked");
559	            }
560	            p.setState(reopened);
561	            audit.record("STATE_CHANGED id=" + id + " from=" + current + " to=" + reopened);
562	            return p;
563	        });
