615	                }
616	                allies.add(people.findBySheetIdAndLocalId(sheetId, allyId)
617	                        .orElseThrow(() -> new IllegalArgumentException("no person " + allyId + " on this sheet")));
618	            }
619	            p.setAllies(allies);
620	            return p;
621	        });
622	    }
