    sheet_id VARCHAR(255) REFERENCES sheet (id) ON DELETE CASCADE,
    local_id BIGINT NOT NULL,
    name VARCHAR(255) NOT NULL,
    sheet_key VARCHAR(255) GENERATED ALWAYS AS (COALESCE(sheet_id, ''))
);
